#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
TOTAL_STAGES=5
PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$PROJECT_ROOT"
ENV_FILE="$PROJECT_ROOT/.env"
command -v node >/dev/null || { warn 'Install Node 24+ first.'; exit 1; }

banner "Your Hindi voice for Family mode"
stage "Review the setup"
step '1. Record 10-25 seconds of your own Hindi voice.'
step '2. Upload the recording and its exact transcript to Boson.'
step '3. Save the returned public voice ID as FAMILY_VOICE in the local .env.'
step '4. Activate that value on the controller you use, then listen in Family mode.'
note 'Quick and Hands-free keep their existing voices. No GitHub secrets are needed.'
note 'The upload uses BOSON_API_KEY already in .env. It must match the hosted controller key.'
confirm 'Use these stages?' || exit 0

stage "Record your Hindi sample"
say 'Use a quiet room and your normal voice. Read this naturally, without music:'
SAMPLE='नमस्ते, मैं रोनित हूँ। कैसे हो आप? मैं आपकी मदद के लिए यहाँ हूँ। आराम से बताइए, फ़ोन पर क्या करना है? हम एक एक करके सब कर लेंगे। कोई जल्दी नहीं है। अगर कुछ समझ न आए तो मुझसे फिर पूछ लेना।'
say "$SAMPLE"
if [[ "$(uname -s)" == Darwin ]]; then
  open -a 'QuickTime Player' || true
  step 'QuickTime Player: File > New Audio Recording. Click Record, read the paragraph, then Stop.'
  step 'File > Save. Save the recording somewhere you can find it.'
else
  step 'Use your recorder and export WAV, MP3, FLAC or Opus (5-30 seconds, under 10 MB).'
fi
while :; do
  ask RECORDING_PATH 'Paste the saved audio file absolute path (no shell escaping):'
  RECORDING_PATH="${RECORDING_PATH#\'}"; RECORDING_PATH="${RECORDING_PATH%\'}"
  RECORDING_PATH="${RECORDING_PATH#\"}"; RECORDING_PATH="${RECORDING_PATH%\"}"
  [[ -f "$RECORDING_PATH" ]] && break
  warn 'File not found. Paste the absolute path, without shell escaping.'
done
case "$RECORDING_PATH" in
  *.[mM]4[aA]|*.[mM][oO][vV])
    command -v afconvert >/dev/null || { warn 'Export a WAV file and rerun.'; exit 1; }
    CONVERTED=$(mktemp "${TMPDIR:-/tmp}/family-voice.XXXXXX")
    afconvert -f WAVE -d LEI16@24000 -c 1 "$RECORDING_PATH" "$CONVERTED"
    RECORDING_PATH="$CONVERTED"
    trap 'rm -f "${CONVERTED:-}"' EXIT
    ;;
esac
note 'The transcript must match what you actually said, including changes or filler words.'
if confirm 'Did you read the displayed paragraph exactly?'; then
  REFERENCE_TEXT="$SAMPLE"
else
  ask REFERENCE_TEXT 'Enter the exact transcript in one line:'
fi
[[ -n "$REFERENCE_TEXT" ]] || { warn 'A transcript is required.'; exit 1; }

stage "Create your Boson voice"
open_url 'https://docs.boson.ai/api-reference/audio/create-a-voice'
note 'This sends your recording and transcript to Boson using the existing .env API key.'
note 'The recording must be at least 3 seconds and at most 10 MB.'
confirm 'Upload your recording to create your voice?' || exit 0
export RECORDING_PATH REFERENCE_TEXT
FAMILY_VOICE=$(node --env-file-if-exists=.env --input-type=module <<'JS'
import { readFile } from 'node:fs/promises';
const key = process.env.BOSON_API_KEY;
if (!key) throw new Error('Missing BOSON_API_KEY in .env. Configure the controller key before rerunning.');
const audio = await readFile(process.env.RECORDING_PATH);
if (audio.byteLength > 10_000_000) throw new Error('Recording exceeds 10 MB. Export a shorter recording.');
const response = await fetch('https://api.boson.ai/v1/audio/voices', {
  method: 'POST',
  headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ ref_audio: audio.toString('base64'), ref_text: process.env.REFERENCE_TEXT, description: 'Ronit Hindi family assistant' }),
  signal: AbortSignal.timeout(120_000),
});
if (!response.ok) throw new Error(`Boson voice creation failed (HTTP ${response.status}). Check key access, credits, recording and transcript.`);
const result = await response.json();
// The OpenAPI uses voice; the guide examples use voice_id.
const voice = result.voice ?? result.voice_id;
if (typeof voice !== 'string' || !/^voice_[a-zA-Z0-9_-]+$/.test(voice)) throw new Error('Boson returned no valid voice ID. Local configuration was not changed.');
process.stdout.write(voice);
JS
)
write_env FAMILY_VOICE "$FAMILY_VOICE"
say "Your Family voice: $FAMILY_VOICE"
pause 'Voice saved locally. Press Enter for activation.'

stage "Activate on your controller"
say "Set FAMILY_VOICE to: $FAMILY_VOICE"
step 'For a hosted controller: add or update its FAMILY_VOICE variable with the value above, then redeploy.'
note 'Use the same BOSON_API_KEY as the local upload. Do not copy API keys into chat.'
step 'Wait until that deployment reports success. A saved variable alone is not activation.'
note 'For a local controller instead: stop the running server and restart it with npm start.'
if ! confirm 'Has your controller restarted successfully with this value?'; then
  warn 'Voice saved locally; controller activation is still pending. Rerun or apply the value later.'
  exit 0
fi

stage "Listen in Family mode"
step 'On the phone, tap Stop listening if a session is running.'
step 'Select Family, then Start listening.'
say 'Say: नमस्ते, मुझसे हिंदी में बात करो। आप मेरी कैसे मदद कर सकते हो?'
note 'Family mode follows the language you speak. Start in Hindi to get Hindi replies.'
step 'Listen for your own voice and natural Hindi. Quick and Hands-free should retain their voices.'
if ! confirm 'Does Family mode now sound like you and reply in Hindi?'; then
  warn 'Listening check did not pass. Keep the voice ID; check controller key, deployment and a fresh Family session.'
  exit 1
fi
finish
say 'Family voice setup and your listening check are complete.'
}

run_wizard "$@"; exit
